import { useSessionVideoQuality } from '@gsm-app/routes/Sessions/routes/SessionView/hooks/useSessionVideoQuality';
import { useSuccessfulSessionsByIds } from '@gsm-app/routes/Sessions/routes/SessionView/hooks/useSuccessfulSessionsByIds';
import { duration as formatDuration } from '@gsm-common/utils/time/duration';
import { createToast } from '@gsm-common/utils/toast/createToast';
import { createWarning } from '@gsm-common/utils/toast/createWarning';
import { IconChevronDown, IconCircleQuestionMark, IconClipboard, IconCopySquare, IconLinkOut } from '@hawkins/assets';
import {
    Badge,
    Button,
    Card,
    CardBody,
    CardHeader,
    Chip,
    Divider,
    SkeletonLoader,
    Stack,
    Text,
    TextLink,
    Tooltip,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import clsx from 'clsx';
import { useCallback, useMemo, useState } from 'react';
import type { GameSession } from '../../hooks/useGameSession';
import { SessionChips } from '../SessionChips';
import { SessionDetailRow } from './SessionDetailRow';
import styles from './SessionDetailsCard.module.css';

export interface SessionDetailsCardProps {
    session: GameSession;
}

const EMPTY_VALUE = '—';

const CopyableValue = ({ value, label }: { value: string; label: string }) => {
    const handleCopy = useCallback(() => {
        try {
            navigator.clipboard.writeText(value);
            createToast({
                title: `${label} copied to clipboard`,
                icon: IconClipboard,
                options: { duration: 1500, id: `copy_${label}` },
            });
        } catch (_e) {
            createWarning({
                title: `${label} copy failed`,
                icon: IconClipboard,
                options: { duration: 1500, id: `copy_fail_${label}` },
            });
        }
    }, [value, label]);

    return (
        <>
            <Text level={0} bold>
                {value}
            </Text>
            <Button icon={IconCopySquare} variant='icon' compact onClick={handleCopy} aria-label={`Copy ${label}`} />
        </>
    );
};

export const SessionDetailsCard = ({ session }: SessionDetailsCardProps) => {
    const [expanded, setExpanded] = useState(true);

    const { videoQuality, error: videoQualityError } = useSessionVideoQuality({
        sessionId: session.id,
        live: session.live,
        videoHeight: session.videoHeight,
        frameRate: session.frameRate,
    });

    const {
        isLoading: successLoading,
        error: successError,
        successfulSessionsById,
    } = useSuccessfulSessionsByIds([session.id]);

    const duration = useMemo(() => {
        if (!session.sessions.length) return null;
        const first = session.sessions[0];
        if (!first.startTime || !first.endTime) return null;
        return formatDuration(first.startTime, first.endTime);
    }, [session.sessions]);

    const timestamp = new Date(Number(session.timestamp.slice(0, 10)) * 1000).toLocaleString();

    const hardwareRevisions = useMemo(
        () => [...new Set(session.sessions.map((s) => s.ocgaHardwareRevision).filter(Boolean))],
        [session.sessions],
    );

    return (
        <Card>
            <CardHeader className={styles.header} dividerBottom title='Session Details'>
                <Button
                    icon={IconChevronDown}
                    className={clsx(styles.chevron, { [styles.chevronCollapsed]: !expanded })}
                    variant='icon'
                    compact
                    onClick={() => setExpanded((prev) => !prev)}
                    aria-expanded={expanded}
                    aria-label={expanded ? 'Collapse session details' : 'Expand session details'}
                />
            </CardHeader>
            {expanded && (
                <CardBody className={styles.body} style={{ padding: 0 }}>
                    <div className={styles.column}>
                        <SessionDetailRow label='Game ID'>
                            <Text level={0} bold>
                                {session.gameId}
                            </Text>
                        </SessionDetailRow>

                        <SessionDetailRow label='Build ID'>
                            <Text level={0} bold>
                                {session.buildId}
                            </Text>
                        </SessionDetailRow>

                        <SessionDetailRow label='Build Label'>
                            <Text level={0} bold>
                                {session.buildLabel}
                            </Text>
                        </SessionDetailRow>

                        {session.ocgaEnv && (
                            <SessionDetailRow label='OCGA Environment'>
                                <Text level={0} bold>
                                    {session.ocgaEnv}
                                </Text>
                            </SessionDetailRow>
                        )}

                        {session.esn && (
                            <SessionDetailRow label='Client ESN'>
                                <CopyableValue value={session.esn} label='Client ESN' />
                            </SessionDetailRow>
                        )}

                        {session.version && (
                            <SessionDetailRow label='Client Version'>
                                <CopyableValue value={session.version} label='Client Version' />
                            </SessionDetailRow>
                        )}

                        {session.esn && session.deviceName && (
                            <SessionDetailRow label='Device'>
                                <Text level={0} bold>
                                    {session.deviceName || session.esn}
                                </Text>
                            </SessionDetailRow>
                        )}

                        <SessionDetailRow label='Session Status'>
                            {successLoading && !successError ? (
                                <SkeletonLoader
                                    height={Dimensions.Size24}
                                    variant='square'
                                    width={Dimensions.Size112}
                                />
                            ) : successError ? (
                                <Text level={0} bold>
                                    N/A
                                </Text>
                            ) : (
                                <Tooltip
                                    label={
                                        successfulSessionsById?.[session.id]
                                            ? 'The session was successful and did not result in an error code'
                                            : 'The session resulted in an error code and did not end successfully'
                                    }
                                >
                                    <Badge compact color={successfulSessionsById?.[session.id] ? 'COMPLETE' : 'DEAD'}>
                                        {successfulSessionsById?.[session.id] ? 'Succeeded' : 'Failed'}
                                    </Badge>
                                </Tooltip>
                            )}
                        </SessionDetailRow>

                        <SessionDetailRow
                            label='Placeholder'
                            labelAdornment={
                                <Tooltip label='Placeholder data is not yet wired up for this session'>
                                    <IconCircleQuestionMark size='small' />
                                </Tooltip>
                            }
                        >
                            <Text level={0} bold>
                                {session.placeholder === undefined ? EMPTY_VALUE : session.placeholder ? 'Yes' : 'No'}
                            </Text>
                        </SessionDetailRow>
                    </div>

                    <Divider
                        variant='vertical'
                        color='xLight'
                        style={{ alignSelf: 'stretch', height: 'auto', marginInline: 0 }}
                    />

                    <div className={styles.column}>
                        <SessionDetailRow label='Player'>
                            {session.player ? (
                                session.playerUrl ? (
                                    <>
                                        <TextLink href={session.playerUrl} target='_blank' rel='noreferrer'>
                                            {session.player}
                                        </TextLink>
                                        <IconLinkOut size='small' />
                                    </>
                                ) : (
                                    <Text level={0} bold>
                                        {session.player}
                                    </Text>
                                )
                            ) : (
                                <Text level={0} bold>
                                    {EMPTY_VALUE}
                                </Text>
                            )}
                        </SessionDetailRow>

                        <SessionDetailRow label='Played On'>
                            <Text level={0} bold>
                                {timestamp}
                            </Text>
                        </SessionDetailRow>

                        {duration && (
                            <SessionDetailRow label='Duration'>
                                <Text level={0} bold>
                                    {duration}
                                </Text>
                            </SessionDetailRow>
                        )}

                        <SessionDetailRow label='Video Quality'>
                            {!videoQuality && !videoQualityError ? (
                                <SkeletonLoader
                                    height={Dimensions.Size24}
                                    variant='square'
                                    width={Dimensions.Size112}
                                />
                            ) : videoQualityError ? (
                                <Text level={0} bold>
                                    N/A
                                </Text>
                            ) : (
                                <Text level={0} bold>
                                    {videoQuality ? `${videoQuality.height}p@${videoQuality.frameRate}` : ''}
                                </Text>
                            )}
                        </SessionDetailRow>

                        <SessionDetailRow label='Placeholder Value'>
                            <Text level={0} bold>
                                {session.placeholderValue ?? EMPTY_VALUE}
                            </Text>
                        </SessionDetailRow>

                        <SessionDetailRow label='OCGA Hostnames'>
                            <SessionChips session={session} />
                        </SessionDetailRow>

                        <SessionDetailRow label='OCGA Versions'>
                            <Stack gap={Dimensions.Space4}>
                                {session.sessions.map((s) => (
                                    <Chip compact key={s.uuid}>
                                        {s.stackVersionBranch}
                                    </Chip>
                                ))}
                            </Stack>
                        </SessionDetailRow>

                        {hardwareRevisions.length > 0 && (
                            <SessionDetailRow label='Hardware Revision'>
                                <Stack gap={Dimensions.Space4}>
                                    {hardwareRevisions.map((revision) => (
                                        <Chip compact key={revision}>
                                            {revision}
                                        </Chip>
                                    ))}
                                </Stack>
                            </SessionDetailRow>
                        )}
                    </div>
                </CardBody>
            )}
        </Card>
    );
};
