import { ROUTE_SESSIONS } from '@gsm-app/constants';
import { type SopAccountType, useSopAccounts } from '@gsm-app/providers/SopAccountProvider';
import { Content } from '@gsm-common/components/Content';
import { Layout } from '@gsm-common/components/Layout';
import { IconMagnifyingGlass } from '@hawkins/assets';
import {
    Button,
    Card,
    Dropdown,
    Input,
    type ListItemProps,
    Loader,
    Stack,
    Text,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { type KeyboardEvent, useCallback, useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { SessionHistoryTable } from '../SessionHistoryTable';
import { useFullStory } from '@gsm-app/hooks/useFullStory';
import { SopAccountDropdownItem } from '@gsm-app/routes/Play/components/PageHeader/components/SopAccountDropdown';
import styles from './NoSessionId.module.css';

export const NoSessionId = () => {
    const inputRef = useRef<HTMLInputElement>(null);
    const navigate = useNavigate();
    const { selectedAccount: sopAccount, isLoading: sopAccountsLoading, savedAccounts } = useSopAccounts();
    const [selectedAccount, setSelectedAccount] = useState<SopAccountType | undefined>();

    const { trackEvent } = useFullStory();

    useEffect(() => {
        if (sopAccount) {
            setSelectedAccount(sopAccount);
        }
    }, [sopAccount?.value]);

    const handleSessionIdChange = useCallback(
        (value: string) => {
            if (value) {
                navigate(`${ROUTE_SESSIONS}/${value}`);
            }
        },
        [navigate],
    );

    const handleSessionIdInputChange = useCallback(
        (e: KeyboardEvent<HTMLInputElement>) => {
            if (e.key === 'Enter') {
                const value = e.target instanceof HTMLInputElement ? e.target.value : '';
                handleSessionIdChange(value);
            }
        },
        [handleSessionIdChange],
    );

    const handleSessionIconClick = useCallback(() => {
        if (inputRef.current) {
            handleSessionIdChange(inputRef.current.value);
        }
    }, [handleSessionIdChange]);

    return (
        <Layout full>
            <Content>
                <Stack style={{ placeItems: 'center', margin: Dimensions.Space4, height: '100%' }} layout={{
                    flexDirection: 'column',
                    display: 'flex'
                }} gap={Dimensions.RawSpace20}>
                    <Card style={{ width: '100%' }}>
                        <Card.Body>
                            <Input
                                inputRef={inputRef}
                                label={<Text variant='label' colorVariant='faded'>Session Id</Text>}
                                placeholder='********-****-****-****-***********'
                                inputProps={{
                                    pattern: /^[A-Za-z0-9\-]+$/,
                                    autoComplete: 'off',
                                    max: 50,
                                }}
                                onKeyUp={handleSessionIdInputChange}
                                endAdornment={
                                    <Button
                                        compact
                                        variant='icon'
                                        icon={IconMagnifyingGlass}
                                        aria-label='Search Session Id'
                                        onClick={handleSessionIconClick}
                                    />
                                }
                            />
                            <div className={styles.separator}>
                                OR
                            </div>

                            <Stack gap={Dimensions.Space24} layout={{
                                display: 'flex',
                                justifyItems: 'stretch',
                            }} orientation='horizontal'>
                                {/* <GameHeaderDropdown
                                    minWidth={Dimensions.RawSize112}
                                    maxWidth={360}
                                /> */}
                                {sopAccountsLoading ? (
                                    <Loader variant='linear' />
                                ) : (
                                    <Stack gap={Dimensions.Space24} style={{
                                        justifyItems: 'center',
                                        flex: 1,
                                    }}>
                                        <Dropdown<SopAccountType>
                                            label={<Text variant='label' colorVariant='faded'>Account</Text>}
                                            onChange={(selected: SopAccountType | null) => {
                                                if (selected) {
                                                    setSelectedAccount(selected);

                                                    trackEvent('Session History Switch Account', {
                                                        email: selected?.value,
                                                    });
                                                }
                                            }}
                                            options={savedAccounts}
                                            value={selectedAccount}
                                            DropdownListItem={(props: ListItemProps<SopAccountType>) => {
                                                return <SopAccountDropdownItem disableActions={true} {...props} />;
                                            }}
                                        />

                                        {!selectedAccount && (
                                            <Text>Select an account to show the session history</Text>
                                        )}
                                    </Stack>
                                )}
                            </Stack>
                        </Card.Body>
                    </Card>
                    <SessionHistoryTable />
                </Stack>
            </Content>
        </Layout>
    );
};
