import { fetch } from '@gsm-app/utils/fetch';
import { useQuery } from '@tanstack/react-query';
import { useMemo } from 'react';

export interface SuccessfulSessionsResponse {
    data?: Record<string, boolean>;
    errors?: {
        title: string;
        detail: string;
    }[];
}

const fetchSuccessfulSessions = async (
    gameplaySessionIds: string[] | undefined,
): Promise<SuccessfulSessionsResponse | undefined> => {
    if (!gameplaySessionIds || gameplaySessionIds.length === 0) {
        return Promise.resolve(undefined);
    }

    const response = await fetch('/api/successful-sessions', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            gameplaySessionIds,
        }),
    });

    if (!response.ok) {
        const errorData = await response.text();
        throw new Error(`Fetch failed with status ${response.status}: ${errorData}`);
    }

    return await response.json();
};

export function useSuccessfulSessionsByIds(gameplaySessionIds: string[] | undefined) {
    const query = useQuery({
        queryKey: ['successful-sessions', gameplaySessionIds],
        queryFn: () => fetchSuccessfulSessions(gameplaySessionIds),
        enabled: Boolean(gameplaySessionIds && gameplaySessionIds.length > 0),
    });

    const successfulSessionsById = useMemo(() => {
        return query.data?.data || {};
    }, [query.data]);

    return {
        ...query,
        successfulSessionsById,
    };
}
