import NetworkActivityTable from '@gsm-app/components/NetworkActivityTable/NetworkActivityTable';
import { useAppQueryParams } from '@gsm-app/hooks/useAppQueryParams';
import { useControllerLogs } from '@gsm-app/hooks/useControllerLogs';
import { useFeature } from '@gsm-app/hooks/useFeature';
import { useLogErrorWarningEvents } from '@gsm-app/hooks/useLogErrorWarningEvents';
import { useSessionGameLogs } from '@gsm-app/hooks/useSessionGameLogs';
import { useSessionTimelineMetrics } from '@gsm-app/hooks/useSessionTimelineMetrics';
import { isOcga2026Session } from '@gsm-app/models/Channel';
import { AllCommunityModule, ModuleRegistry } from 'ag-grid-community';
import { useCallback, useMemo, useState } from 'react';
import useDimensions from 'react-cool-dimensions';
import { NETWORK, OVERVIEW, PERFORMANCE } from '../../constants';
import type { GameSession } from '../../hooks/useGameSession';
import { useSessionVideoQuality } from '../../hooks/useSessionVideoQuality';
import type { Playhead } from '../../types';
import { OverviewTab } from '../OverviewTab/OverviewTab';
import { PerformanceTab } from '../PerformanceTab/PerformanceTab';

export interface PageContentProps {
    session?: GameSession;
    currentTab: string;
    onTabChange: (tab: string) => void;
}

export const PageContent = ({ session, currentTab, onTabChange }: PageContentProps) => {
    const sessionId = session?.id;
    const { observe: dimensionsRef } = useDimensions<HTMLElement>();

    const { gameId: urlGameId } = useAppQueryParams();
    const gameId = urlGameId ?? session?.gameId;
    const { resourceEnvelope } = useFeature(gameId);

    const isLive = Boolean(session?.live);
    const isOcga2026 = isOcga2026Session(session?.sessions?.[0]?.ocgaHardwareRevision);
    const activeEnvelope = isOcga2026 ? resourceEnvelope : null;
    const hidePerfGraphs = resourceEnvelope != null && !isOcga2026;
    const disablePerfGraphsNoEnvelope = isOcga2026 && resourceEnvelope == null;

    const { videoQuality } = useSessionVideoQuality({
        sessionId,
        live: isLive,
        disabled: Boolean(session?.videoHeight),
    });
    const videoResolution = session?.videoHeight ?? videoQuality?.height;

    // Lifted here so WebSocket connections and data persist across tab switches.
    const gameLogs = useSessionGameLogs({ sessionId, live: isLive });
    const controllerLogs = useControllerLogs({ sessionId });

    // Same t=0 reference used by the graph/logs sync — computed here too so a jump initiated
    // from the Overview tab's error table can be converted to "seconds from session start"
    // before the Performance tab even mounts.
    const sessionStartMs = useMemo(
        () => (session?.timestamp ? Number(session.timestamp.slice(0, 10)) * 1000 : 0),
        [session?.timestamp],
    );

    // Lifted here (rather than owned by PerformanceTab) so the Overview tab's error table can
    // also read it, and so a jump from Overview survives the tab switch to Performance.
    const [playhead, setPlayhead] = useState<Playhead>(null);
    const onGraphPlayhead = useCallback((time: number) => {
        setPlayhead({ time, source: 'graph' });
    }, []);
    const onLogPlayhead = useCallback((time: number) => {
        setPlayhead({ time, source: 'log' });
    }, []);

    // Derived once here (rather than separately in the Overview and Performance tabs) so both
    // surfaces always agree on exactly the same set of error/warning events.
    const errorWarningEvents = useLogErrorWarningEvents(gameLogs.data, controllerLogs.data);

    // Overview tab's error table -> Performance graph: jump the shared playhead to the clicked
    // occurrence's exact time and switch tabs so the graph is immediately visible.
    const onJumpToTime = useCallback(
        (date: Date) => {
            const seconds = (date.getTime() - sessionStartMs) / 1000;
            setPlayhead({ time: seconds, source: 'log' });
            onTabChange(PERFORMANCE);
        },
        [sessionStartMs, onTabChange],
    );

    const { datasets, targetInstanceCount, error, exportOrder, loading } = useSessionTimelineMetrics({
        gameId,
        sessionId,
        live: isLive,
        disabled: !sessionId || hidePerfGraphs || disablePerfGraphsNoEnvelope,
        resourceEnvelope: activeEnvelope,
        videoResolution,
    });

    useMemo(() => {
        ModuleRegistry.registerModules([AllCommunityModule]);
    }, []);

    return (
        <div ref={dimensionsRef as any} style={{ overflow: 'hidden', height: '100%', position: 'relative' }}>
            {currentTab === OVERVIEW && session && (
                <OverviewTab session={session} errorWarningEvents={errorWarningEvents} onJumpToTime={onJumpToTime} />
            )}

            {currentTab === PERFORMANCE && (
                <PerformanceTab
                    session={session}
                    datasets={datasets as { [key: string]: any }}
                    targetInstanceCount={targetInstanceCount}
                    error={error}
                    exportOrder={exportOrder}
                    loading={loading}
                    activeEnvelope={activeEnvelope ?? null}
                    hidePerfGraphs={hidePerfGraphs}
                    disablePerfGraphsNoEnvelope={disablePerfGraphsNoEnvelope}
                    sessionId={sessionId}
                    gameLogs={gameLogs}
                    controllerLogs={controllerLogs}
                    isLive={isLive}
                    playhead={playhead}
                    onGraphPlayhead={onGraphPlayhead}
                    onLogPlayhead={onLogPlayhead}
                    errorWarningEvents={errorWarningEvents}
                />
            )}

            {currentTab === NETWORK && <NetworkActivityTable gameId={session?.gameId} sessionId={sessionId} />}
        </div>
    );
};
