import { useCallback, useEffect, useState } from 'react';
import type { Message } from '@gsm-app/models/Message';
import { useTelemetry } from '../../../../../hooks/useTelemetry';
import { MICROSECONDS_PER_SECOND } from '@gsm-app/constants';

type UseSessionVideoQualityProps = {
    sessionId?: string | undefined;
    live?: boolean;
    videoHeight?: number;
    frameRate?: number;
    disabled?: boolean;
};

export type VideoQuality = {
    width: number;
    height: number;
    frameRate?: number;
};

/**
 * Hook to extract video quality information (resolution and FPS) from GameplaySessionStats telemetry messages.
 * Uses the 'session' websocket context to receive raw GameplaySessionStats events and parses the
 * VideoFrameStats to extract EncodedWidth, EncodedHeight, and TargetInterval.
 * Returns the video quality from the first message received, or undefined if not yet available.
 */
export const useSessionVideoQuality = ({
    sessionId,
    live,
    videoHeight,
    frameRate,
    disabled: disabledProp = false,
}: UseSessionVideoQualityProps) => {
    const hasSessionVideoConfig = Boolean(videoHeight && frameRate);
    const [videoQuality, setVideoQuality] = useState<VideoQuality | undefined>(undefined);
    const [error, setError] = useState<any>(undefined);

    // Set video quality from session info, or reset when session changes
    useEffect(() => {
        if (videoHeight && frameRate) {
            setVideoQuality({ width: 0, height: videoHeight, frameRate });
        } else {
            setVideoQuality(undefined);
        }
    }, [sessionId, videoHeight, frameRate]);

    const onMessage = useCallback(
        (message: Message) => {
            // Skip if we already have video quality
            if (videoQuality) {
                return;
            }

            // Parse raw GameplaySessionStats message
            // biome-ignore lint/suspicious/noExplicitAny: Telemetry message structure is dynamic
            const data = message.data as any;

            // Check if this is a GameplaySessionStats message
            if (data?.Message?.$case === 'GameplaySessionStats') {
                const stats = data.Message.GameplaySessionStats;
                const deviceStats = stats?.GameplayDeviceStats;

                if (deviceStats && Array.isArray(deviceStats) && deviceStats.length > 0) {
                    for (const device of deviceStats) {
                        const videoStats = device?.VideoFrameStats;
                        if (videoStats) {
                            const width = videoStats.EncodedWidth;
                            const height = videoStats.EncodedHeight;
                            const targetInterval = videoStats.TargetInterval;

                            if (width && height) {
                                // Calculate frame rate from target interval (microseconds)
                                // e.g., 30 FPS = 33333us, 60 FPS = 16667us
                                let frameRate: number | undefined = undefined;
                                if (typeof targetInterval === 'number' && targetInterval > 0) {
                                    frameRate = Math.round(MICROSECONDS_PER_SECOND / targetInterval);
                                }

                                setVideoQuality({
                                    width: typeof width === 'number' ? width : Number(width),
                                    height: typeof height === 'number' ? height : Number(height),
                                    frameRate,
                                });
                                return; // Stop processing once we have the data
                            }
                        }
                    }
                }
            }
        },
        [videoQuality],
    );

    const onError = useCallback((error: any) => {
        setError(error);
    }, []);

    useTelemetry({
        sessionId,
        live,
        disabled: disabledProp || hasSessionVideoConfig || !!videoQuality, // Skip if caller disabled, session has video config, or we have data
        context: 'session',
        onMessage,
        onError,
    });

    return {
        videoQuality,
        error,
    };
};
