import { IconCircleI, IconSortColumnAscending, IconSortColumnDescending } from "@hawkins/assets";
import { Tooltip } from "@hawkins/components";
import type { CustomHeaderProps } from "@hawkins/table-next";
import { Dimensions } from "@hawkins/variables";
import styles from "./SessionTimestampHeader.module.css";

export const SessionTimestampHeader = (props: CustomHeaderProps) => {
    const onSortRequested = (event: React.MouseEvent | React.KeyboardEvent) => {
        if ('key' in event && event.key !== 'Enter' && event.key !== ' ') {
            return;
        }
        props.progressSort('shiftKey' in event ? event.shiftKey : false);
    };

    const sortState = props.column.getSort();
    let sortIcon = null;
    if (sortState === 'asc') {
        sortIcon = <IconSortColumnAscending size="small" color="primary" style={{ marginLeft: Dimensions.Space4 }} />;
    } else if (sortState === 'desc') {
        sortIcon = <IconSortColumnDescending size="small" color="primary" style={{ marginLeft: Dimensions.Space4 }} />;
    }

    return (
        <div
            className={styles.headerWrapper}
            onClick={onSortRequested}
            onKeyDown={onSortRequested}
            role="button"
            tabIndex={0}
            aria-label={`${props.displayName} - Click to sort`}
        >
            <div className={styles.headerContent}>
                <span className={styles.headerText}>
                    {props.displayName}
                </span>
                {sortIcon}
            </div>
            <Tooltip label="Timestamp within the game session when the file was created">
                <IconCircleI size="small" className={styles.infoIcon} />
            </Tooltip>
        </div>
    );
};
