/**
 * Normalizes a log message into a stable "template" so repeated occurrences of the same
 * underlying issue — which in practice usually only differ by an embedded frame number, byte
 * count, address, or id — collapse into a single group instead of flooding the table with
 * hundreds of near-duplicate rows.
 */
export function templatizeMessage(message: string): string {
    return message
        .replace(/0x[0-9a-fA-F]+/g, '<hex>')
        .replace(/\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b/g, '<uuid>')
        .replace(/\b\d+\.\d+\b/g, '<num>')
        .replace(/\b\d+\b/g, '<num>')
        .trim();
}
