import { HoverCardTooltip } from '@gsm-common/components/HoverCardTooltip';
import { enumKey } from '@gsm-common/utils/enum/enumKey';
import { duration } from '@gsm-common/utils/time/duration';
import { IconCheckmark, IconWarning } from '@hawkins/assets';
import { ButtonGroup, Chip, Text } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { MessageType, type Session, Stop } from '@ocga/proto';
import type { GameSession, SessionEvent } from '../../hooks/useGameSession';

const sessionIcon = (success: boolean) => {
    if (success) {
        return <IconCheckmark size='small' />;
    }
    return <IconWarning size='small' />;
};

interface SessionChipsProps {
    session: GameSession;
}

const gameplayStoppedEvent = (events: SessionEvent[]) => {
    const event = events.find(e => e.messageType === MessageType.MessageType.GameplayStoppedEvent);
    return event?.message?.$case === 'GameplayStoppedEvent' ? event.message.GameplayStoppedEvent : undefined;
};

const sessionSuccess = (event: Session.GameplayStoppedEvent | undefined) => {
    if (!event) {
        return true;
    }
    // success when stopped by user
    return event.StopReason === Stop.Reason.User;
};

export const SessionChips = ({ session }: SessionChipsProps) => {
    return (
        <ButtonGroup gap={Dimensions.Space1}>
            {session.sessions.map((s, i) => {
                const stoppedEvent = gameplayStoppedEvent(s.events);
                const lastSession = i === session.sessions.length - 1;
                const success = lastSession && sessionSuccess(stoppedEvent);
                return (
                    <HoverCardTooltip
                        key={s.machineHostname}
                        label={[
                            lastSession && session.live ? (
                                'Session in progress'
                            ) : (
                                <div>
                                    <Text>Session has ended</Text>
                                    {stoppedEvent && (
                                        <>
                                            <Text>
                                                <b>Detail:</b>
                                                {` ${enumKey(Stop.Detail, stoppedEvent.StopDetail)}`}
                                            </Text>
                                            <Text>
                                                <b>Reason:</b>
                                                {` ${enumKey(Stop.Reason, stoppedEvent.StopReason)}`}
                                            </Text>
                                        </>
                                    )}
                                    <Text>
                                        <b>Duration:</b>
                                        {` ${duration(s.startTime, s.endTime)}`}
                                    </Text>
                                </div>
                            ),
                        ]}
                        placement='top-start'
                    >
                        <Chip compact startAdornment={sessionIcon(success)}>
                            {s.machineHostname}
                        </Chip>
                    </HoverCardTooltip>
                );
            })}
        </ButtonGroup>
    );
};
