import { ROUTE_SESSIONS } from '@gsm-app/constants';
import { Content } from '@gsm-common/components/Content';
import { Layout } from '@gsm-common/components/Layout';
import { Announcement, Stack } from '@hawkins/components';
import { useNavigate } from 'react-router-dom';

export const NoSessionFound = () => {
    const nav = useNavigate();
    return (
        <Layout full>
            <Content>
                <Stack style={{ placeItems: 'center', paddingTop: 20 }}>
                    <Announcement title='No Session Found!' primaryActionHandler={() => nav(ROUTE_SESSIONS)}>
                        Make sure the id is correct. Session data is removed periodically.
                    </Announcement>
                </Stack>
            </Content>
        </Layout>
    );
};
