import type { GameSession } from '@gsm-app/routes/Sessions/routes/SessionView/hooks/useGameSession';
import { IconDownload, IconX } from '@hawkins/assets';
import { Button, Text } from '@hawkins/components';
import {
    type ColDef,
    type GetRowIdParams,
    type ICellRendererParams,
    type RowSelectionOptions,
    type GridApi,
    TableNext,
} from '@hawkins/table-next';
import { useCallback, useState, useMemo } from 'react';
import { useSessionGameFiles } from '@gsm-app/hooks/useSessionGameFiles';
import { createError } from '@gsm-common/utils/toast/createError';
import { SessionTimestampHeader } from './SessionTimestampHeader';
import styles from './SessionFilesTable.module.css';

export type SessionFilesTableProps = {
    session?: GameSession;
};

type RowData = {
    id: string;
    fileName: string;
    fileSize: number;
    sessionTimestamp: string;
    utcTimestamp: string;
};

// Constants
const BYTES_PER_KILOBYTE = 1024;
const FILE_SIZE_UNITS = ['B', 'KB', 'MB', 'GB'];
const MILLISECONDS_IN_MICROSECOND_TIMESTAMP = 13;
const DEFAULT_PAGINATION_PAGE_SIZE = 20;

const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 B';
    const i = Math.floor(Math.log(bytes) / Math.log(BYTES_PER_KILOBYTE));
    return `${Math.round((bytes / BYTES_PER_KILOBYTE ** i) * 100) / 100} ${FILE_SIZE_UNITS[i]}`;
};

const formatSessionTimestamp = (seconds?: number): string => {
    if (seconds === undefined) return '--:--:--';
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
};

const formatUtcTimestamp = (timestamp: string): string => {
    try {
        // Timestamp is in microseconds (first 13 chars = milliseconds since epoch)
        const ms = Number(timestamp.slice(0, MILLISECONDS_IN_MICROSECOND_TIMESTAMP));
        const date = new Date(ms);
        return `${date.toISOString().replace('T', ' ').slice(0, 19)} UTC`;
    } catch (e) {
        return 'Invalid timestamp';
    }
};

export const SessionFilesTable = (props: SessionFilesTableProps) => {
    const { session } = props;

    const [gridApi, setGridApi] = useState<GridApi<RowData> | null>(null);
    const [selectedCount, setSelectedCount] = useState(0);

    const sessionStartTime = session?.sessions?.[0]?.startTime;

    const { files: rawFiles, isLoading } = useSessionGameFiles({
        sessionId: session?.id,
        sessionStartTime,
        live: true,
    });

    // Transform the raw files into table row data
    const files: RowData[] = useMemo(() => {
        return rawFiles.map((file) => ({
            id: file.ID,
            fileName: file.filename,
            fileSize: file.fileSizeBytes,
            sessionTimestamp: formatSessionTimestamp(file.secondsFromSessionStart),
            utcTimestamp: formatUtcTimestamp(file.uploadTimestamp),
        }));
    }, [rawFiles]);

    const fetchAndDownload = useCallback(
        async (fileId: string) => {
            if (!session?.id) return;
            try {
                const response = await fetch(`/api/sessions/${session.id}/gamefiles/${fileId}/download`);
                if (!response.ok) {
                    throw new Error(`Server returned ${response.status}`);
                }
                const { downloadUrl } = await response.json();
                window.open(downloadUrl, '_blank', 'noopener,noreferrer');
            } catch (err) {
                createError({
                    title: 'Download Failed',
                    body: 'Failed to generate download link. Please try again.',
                });
            }
        },
        [session?.id],
    );

    const rowSelection = useMemo<RowSelectionOptions<RowData>>(() => {
        return { mode: 'multiRow', checkboxes: true };
    }, []);

    const onRowSelected = useCallback(() => {
        if (gridApi) {
            const selected = gridApi.getSelectedRows();
            setSelectedCount(selected.length);
        }
    }, [gridApi]);

    const handleDownloadSelected = useCallback(() => {
        if (!gridApi || !session?.id) return;
        const selectedRows = gridApi.getSelectedRows();
        if (selectedRows.length === 0) return;

        if (selectedRows.length === 1) {
            fetchAndDownload(selectedRows[0].id);
            return;
        }

        const fileIds = selectedRows.map((r) => r.id).join(',');
        const a = document.createElement('a');
        a.href = `/api/sessions/${session.id}/gamefiles/bulk-download?fileIds=${fileIds}`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    }, [gridApi, session?.id, fetchAndDownload]);

    const handleClearSelection = useCallback(() => {
        if (gridApi) {
            gridApi.deselectAll();
        }
    }, [gridApi]);

    const columnDefinitions: ColDef<RowData>[] = [
        {
            headerName: 'File Name',
            field: 'fileName',
            sortable: true,
            filter: true,
            flex: 2,
        },
        {
            headerName: 'File Size',
            field: 'fileSize',
            sortable: true,
            cellRenderer: (params: ICellRendererParams<RowData, number>) => {
                return formatFileSize(params.value || 0);
            },
            filter: false,
            flex: 1,
        },
        {
            headerName: 'Session Timestamp',
            field: 'sessionTimestamp',
            sortable: true,
            filter: false,
            flex: 1,
            headerComponent: SessionTimestampHeader,
        },
        {
            headerName: 'UTC Timestamp',
            field: 'utcTimestamp',
            sortable: true,
            filter: false,
            flex: 1.5,
        },
        {
            headerName: 'Download',
            sortable: false,
            filter: false,
            flex: 2,
            cellRenderer: (params: ICellRendererParams<RowData, boolean>) => {
                return (
                    <Button
                        icon={IconDownload}
                        onClick={() => params.data && fetchAndDownload(params.data.id)}
                        variant='tertiary'
                    >
                        Download
                    </Button>
                );
            },
        },
    ];

    const getRowId = (params: GetRowIdParams<RowData>) => {
        return params.data.id;
    };

    return (
        <div className={styles.container}>
            <TableNext<RowData>
                rowData={files}
                columnDefs={columnDefinitions}
                pagination={true}
                paginationPageSize={DEFAULT_PAGINATION_PAGE_SIZE}
                rowSelection={rowSelection}
                onRowSelected={onRowSelected}
                onGridReady={(params) => setGridApi(params.api)}
                getRowId={getRowId}
                domLayout='autoHeight'
                className={styles.table}
                loading={isLoading}
                noRowsOverlayComponent={() => <Text>No files available</Text>}
            />

            {selectedCount > 0 && (
                <div className={styles.selectionBanner}>
                    <div className={styles.selectionInfo}>
                        <span className={styles.selectionText}>
                            {selectedCount} {selectedCount === 1 ? 'file' : 'files'} selected
                        </span>
                    </div>
                    <div className={styles.selectionActions}>
                        <Button icon={IconDownload} onClick={handleDownloadSelected} variant='primary'>
                            Download Selected
                        </Button>
                        <Button icon={IconX} onClick={handleClearSelection} variant='secondary'>
                            Clear Selection
                        </Button>
                    </div>
                </div>
            )}
        </div>
    );
};
