import { MultiSourceLogPanel } from '@gsm-app/components/LogViewer';
import {
    SessionPerformanceChart,
    type SessionPerformanceChartProps,
} from '@gsm-app/components/SessionPerformanceChart';
import { SessionSummaryBanner } from '@gsm-app/components/SessionSummaryBanner/SessionSummaryBanner';
import { generatePerformanceSummary } from '@gsm-app/components/SessionSummaryBanner/generatePerformanceSummary';
import type { LogErrorWarningEvent } from '@gsm-app/hooks/useLogErrorWarningEvents';
import type { ErrorMessage } from '@gsm-app/models/ErrorMessage';
import { ChartType } from '@ncgt/session-timeline/src/types';
import { useEffect, useMemo, useState } from 'react';
import { Panel, PanelGroup, PanelResizeHandle } from 'react-resizable-panels';
import type { Playhead } from '../../types';
import styles from './PerformanceTab.module.css';

export interface PerformanceTabProps extends SessionPerformanceChartProps {
    sessionId?: string;
    gameLogs: {
        data: string[][];
        loading: boolean;
        error: ErrorMessage | undefined;
        clearLogs: () => void;
        completed?: boolean;
    };
    controllerLogs: {
        data: string[][];
        loading: boolean;
        error: ErrorMessage | undefined;
        clearLogs: () => void;
    };
    isLive: boolean;
    /** Shared with the Overview tab's error table so a marker click there can jump the graph here. */
    playhead: Playhead;
    onGraphPlayhead: (seconds: number) => void;
    onLogPlayhead: (seconds: number) => void;
    errorWarningEvents: LogErrorWarningEvent[];
}

export const PerformanceTab = ({
    session,
    datasets,
    targetInstanceCount,
    error,
    exportOrder,
    loading,
    activeEnvelope,
    hidePerfGraphs,
    disablePerfGraphsNoEnvelope,
    sessionId,
    gameLogs,
    controllerLogs,
    isLive,
    playhead,
    onGraphPlayhead,
    onLogPlayhead,
    errorWarningEvents,
}: PerformanceTabProps) => {
    // Canonical t=0 reference shared by the graph and the logs, so a "currentTime" of N seconds
    // means the same absolute instant on both sides regardless of how each independently derives it.
    const sessionStartMs = useMemo(
        () => (session?.timestamp ? Number(session.timestamp.slice(0, 10)) * 1000 : 0),
        [session?.timestamp],
    );

    // AI performance summary — generated from STATS points whenever they're available,
    // independent of whether a resource envelope is active (the server already computes
    // percentAllotted* against the default/target instance count when no envelope override
    // applies). Only shown here on the Performance tab, above the graph/log split.
    const performanceSummary = useMemo(() => {
        if (loading || hidePerfGraphs || disablePerfGraphsNoEnvelope) return null;
        const statsPoints: any[] = (datasets as any)?.[ChartType.STATS] ?? [];
        if (statsPoints.length === 0) return null;
        return generatePerformanceSummary(statsPoints);
    }, [loading, hidePerfGraphs, disablePerfGraphsNoEnvelope, datasets]);

    const [summaryDismissed, setSummaryDismissed] = useState(false);
    // biome-ignore lint/correctness/useExhaustiveDependencies: intentionally reset dismissal when switching sessions
    useEffect(() => {
        setSummaryDismissed(false);
    }, [sessionId]);

    return (
        <div className={styles.root}>
            {performanceSummary && !summaryDismissed && (
                <SessionSummaryBanner summary={performanceSummary} onDismiss={() => setSummaryDismissed(true)} />
            )}
            <PanelGroup direction='horizontal' className={styles.split} autoSaveId='performance-tab-split'>
                {/* Left: Perf graph */}
                <Panel defaultSize={42} minSize={20}>
                    <div className={styles.graphPanel}>
                        <SessionPerformanceChart
                            session={session}
                            datasets={datasets}
                            targetInstanceCount={targetInstanceCount}
                            error={error}
                            exportOrder={exportOrder}
                            loading={loading}
                            activeEnvelope={activeEnvelope}
                            hidePerfGraphs={hidePerfGraphs}
                            disablePerfGraphsNoEnvelope={disablePerfGraphsNoEnvelope}
                            currentTime={playhead?.time ?? null}
                            sessionStartMs={sessionStartMs}
                            playheadSource={playhead?.source ?? null}
                            onGraphPlayhead={onGraphPlayhead}
                            errorWarningEvents={errorWarningEvents}
                        />
                    </div>
                </Panel>

                <PanelResizeHandle className={styles.resizeHandle} />

                {/* Right: Controller + Game logs, with source/layout/type controls */}
                <Panel defaultSize={58} minSize={20}>
                    <div className={styles.logsPanel}>
                        <MultiSourceLogPanel
                            sessionId={sessionId}
                            namePrefix='perf_tab'
                            gameLogs={gameLogs}
                            controllerLogs={controllerLogs}
                            idleMessage='No logs recorded for this session'
                            showControllerStatusBar={false}
                            defaultLogView='all'
                            defaultLayoutMode='single'
                            streamingComplete={Boolean(gameLogs.completed) || isLive}
                            currentTime={playhead?.time ?? null}
                            sessionStartMs={sessionStartMs}
                            playheadSource={playhead?.source ?? null}
                            onSelectLog={onLogPlayhead}
                        />
                    </div>
                </Panel>
            </PanelGroup>
        </div>
    );
};
