import { Layout } from '@gsm-common/components/Layout';
import { useSearchParams } from '@gsm-common/hooks/useSearchParams';
import { Loader } from '@hawkins/components';
import { useCallback } from 'react';
import { useParams } from 'react-router-dom';
import { NoSessionFound } from './components/NoSessionFound';
import { NoSessionId } from './components/NoSessionId';
import { PageContent } from './components/PageContent';
import { PageHeader } from './components/PageHeader';
import { OVERVIEW } from './constants';
import { useGameSession } from './hooks/useGameSession';

const SessionDetail = ({ session }: { session: NonNullable<ReturnType<typeof useGameSession>['data']> }) => {
    const [params, setParams] = useSearchParams<{ tab: string | undefined }>({
        tab: OVERVIEW,
    });
    const onTabChange = useCallback(
        (value: string) => {
            setParams(() => ({ tab: value }));
        },
        [setParams],
    );

    const currentTab = params.tab ?? OVERVIEW;

    return (
        <Layout full>
            <PageHeader session={session} currentTab={currentTab} onTabChange={onTabChange} />
            <PageContent session={session} currentTab={currentTab} onTabChange={onTabChange} />
        </Layout>
    );
};

export const SessionView = () => {
    const { sessionId } = useParams<{ sessionId: string }>();
    const { loading, data: session } = useGameSession(sessionId);

    if (!sessionId) {
        return <NoSessionId />;
    }

    if (loading) {
        return <Loader variant='linear' />;
    }

    if (!session) {
        return <NoSessionFound />;
    }

    return <SessionDetail session={session} />;
};
