import { ROUTE_SESSIONS } from '@gsm-app/constants';
import { createToast } from '@gsm-common/utils/toast/createToast';
import { createWarning } from '@gsm-common/utils/toast/createWarning';
import { duration as formatDuration } from '@gsm-common/utils/time/duration';
import { IconClipboard } from '@hawkins/assets';
import {
    Badge,
    Box,
    Breadcrumb,
    Button,
    Divider,
    HeroBanner,
    Stack,
    Text,
    TextLink,
    ToggleButton,
    ToggleButtonGroup,
    Tooltip,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { useCallback, useMemo } from 'react';
import { NavLink } from 'react-router-dom';
import { OVERVIEW, PERFORMANCE, NETWORK } from '../../constants';
import type { GameSession } from '../../hooks/useGameSession';
import styles from './PageHeader.module.css';

interface PageHeaderProps {
    session: GameSession;
    currentTab: string;
    onTabChange?: (value: string) => void;
}

export const PageHeader = ({ session, currentTab, onTabChange }: PageHeaderProps) => {
    const handleCopySessionId = useCallback(() => {
        try {
            navigator.clipboard.writeText(session.id);
            createToast({
                title: 'Session ID copied to clipboard',
                icon: IconClipboard,
                options: { duration: 1500, id: `session_copy_${session?.id}` },
            });
        } catch (_e) {
            createWarning({
                title: 'Session ID copy failed',
                icon: IconClipboard,
                options: { duration: 1500, id: `session_copy_fail_${session?.id}` },
            });
        }
    }, [session]);

    const duration = useMemo(() => {
        if (!session.sessions.length) return null;
        const first = session.sessions[0];
        if (!first.startTime || !first.endTime) return null;
        return formatDuration(first.startTime, first.endTime);
    }, [session.sessions]);

    const timestamp = new Date(Number(session.timestamp.slice(0, 10)) * 1000).toLocaleString();

    return (
        <HeroBanner
            classes={{
                titleComponent: styles.title,
                metadata: styles.metadata,
                contentWrapper: styles.contentWrapper,
                topComponent: styles.topComponent,
            }}
            height='auto'
            topComponent={
                <div className={styles.topComponentInner}>
                    {/* Row 1: Breadcrumb bar */}
                    <Box
                        alignItems='center'
                        display='flex'
                        justifyContent='space-between'
                        paddingLeft={Dimensions.Space16}
                        paddingRight={Dimensions.Space16}
                        paddingTop={Dimensions.Space16}
                        paddingBottom={Dimensions.Space8}
                    >
                        <Breadcrumb>
                            <TextLink to={ROUTE_SESSIONS} component={NavLink}>
                                Sessions
                            </TextLink>
                            <Stack
                                orientation='horizontal'
                                gap={Dimensions.Space4}
                                layout={{ alignItems: 'center' }}
                            >
                                <TextLink selected>{session.id ?? ''}</TextLink>
                                <Button
                                    icon={IconClipboard}
                                    variant='icon'
                                    compact
                                    onClick={handleCopySessionId}
                                    aria-label='Copy Session ID'
                                />
                            </Stack>
                        </Breadcrumb>
                    </Box>

                    {/* Horizontal divider between row 1 and row 2 */}
                    <Divider style={{ marginBlock: 0 }} />

                    {/* Row 2: ToggleButtonGroup (left) | vertical divider | metadata (right) */}
                    <div className={styles.secondRow}>
                        <ToggleButtonGroup
                            value={currentTab}
                            onChange={(_, value) => { if (typeof value === 'string') onTabChange?.(value); }}
                        >
                            <ToggleButton value={OVERVIEW}>Overview</ToggleButton>
                            <ToggleButton value={PERFORMANCE}>Performance</ToggleButton>
                            <ToggleButton value={NETWORK}>Network</ToggleButton>
                        </ToggleButtonGroup>

                        <Divider orientation='vertical' emphasis='low' style={{ alignSelf: 'stretch', height: 'auto', marginInline: 0 }} />

                        {/* Metadata fields — right aligned */}
                        <Box
                            display='flex'
                            flexWrap='wrap'
                            flexDirection='row'
                            alignItems='center'
                            gap={`${Dimensions.Space8} ${Dimensions.Space24}`}
                            style={{ flex: 1, justifyContent: 'flex-end' }}
                        >
                            <Stack gap={Dimensions.Space2}>
                                <Text level={-1} colorVariant='faded'>Game Name</Text>
                                <Text level={-1} bold>{session.gameName}</Text>
                            </Stack>

                            <Stack gap={Dimensions.Space2}>
                                <Text level={-1} colorVariant='faded'>Session Status</Text>
                                <Tooltip
                                    label={session.live ? 'Status change is delayed' : 'Session was closed.'}
                                    placement='top-start'
                                >
                                    <Badge color={session.live ? 'COMPLETE' : 'DEAD'} compact>
                                        {session.live ? 'Live' : 'Ended'}
                                    </Badge>
                                </Tooltip>
                            </Stack>

                            <Stack gap={Dimensions.Space2}>
                                <Text level={-1} colorVariant='faded'>Played On</Text>
                                <Text level={-1} bold>{timestamp}</Text>
                            </Stack>

                            {duration && (
                                <Stack gap={Dimensions.Space2}>
                                    <Text level={-1} colorVariant='faded'>Duration</Text>
                                    <Text level={-1} bold>{duration}</Text>
                                </Stack>
                            )}
                        </Box>
                    </div>
                </div>
            }
        >
            {/* HeroBanner children area intentionally empty — layout lives in topComponent */}
            <div />
        </HeroBanner>
    );
};
