import { SessionFilesTable } from '@gsm-app/components/SessionFilesTable';
import type { LogErrorWarningEvent } from '@gsm-app/hooks/useLogErrorWarningEvents';
import { IconChevronDown } from '@hawkins/assets';
import { Box, Button, Card, CardBody, CardHeader } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import clsx from 'clsx';
import { useState } from 'react';
import type { GameSession } from '../../hooks/useGameSession';
import { SessionDetailsCard } from '../SessionDetailsCard';
import { SessionErrorsTable } from '../SessionErrorsTable/SessionErrorsTable';
import styles from './OverviewTab.module.css';

export interface OverviewTabProps {
    session: GameSession;
    errorWarningEvents: LogErrorWarningEvent[];
    onJumpToTime: (date: Date) => void;
}

export const OverviewTab = ({ session, errorWarningEvents, onJumpToTime }: OverviewTabProps) => {
    const [filesExpanded, setFilesExpanded] = useState(false);
    const [errorsExpanded, setErrorsExpanded] = useState(true);

    return (
        <div className={styles.container}>
            <SessionDetailsCard session={session} />

            <Card>
                <CardHeader className={styles.header} dividerBottom={filesExpanded} title='Session Files'>
                    <Button
                        icon={IconChevronDown}
                        className={clsx(styles.chevron, { [styles.chevronCollapsed]: !filesExpanded })}
                        variant='icon'
                        compact
                        onClick={() => setFilesExpanded((prev) => !prev)}
                        aria-expanded={filesExpanded}
                        aria-label={filesExpanded ? 'Collapse session files' : 'Expand session files'}
                    />
                </CardHeader>
                {filesExpanded && (
                    <CardBody style={{ padding: 0 }}>
                        <Box padding={Dimensions.Space24}>
                            <SessionFilesTable session={session} />
                        </Box>
                    </CardBody>
                )}
            </Card>

            <Card>
                <CardHeader className={styles.header} dividerBottom={errorsExpanded} title='Session errors and events'>
                    <Button
                        icon={IconChevronDown}
                        className={clsx(styles.chevron, { [styles.chevronCollapsed]: !errorsExpanded })}
                        variant='icon'
                        compact
                        onClick={() => setErrorsExpanded((prev) => !prev)}
                        aria-expanded={errorsExpanded}
                        aria-label={errorsExpanded ? 'Collapse session errors' : 'Expand session errors'}
                    />
                </CardHeader>
                {errorsExpanded && (
                    <CardBody style={{ padding: 0 }}>
                        <Box padding={Dimensions.Space24}>
                            <SessionErrorsTable events={errorWarningEvents} onJumpToTime={onJumpToTime} />
                        </Box>
                    </CardBody>
                )}
            </Card>
        </div>
    );
};
