import { useQuery } from '@tanstack/react-query';
import { useEffect, useMemo } from 'react';
import { createError } from '@gsm-common/utils/toast/createError';
import {
    MILLISECONDS_PER_SECOND,
    MICROSECONDS_PER_MILLISECOND,
    ERROR_TOAST_DURATION_MS,
} from '@gsm-app/constants';
import type { BagpiperRecord } from '@ncgt/common/models/external/bagpiper';

// Constants
const POLLING_INTERVAL_MS = 5000;
const SECONDS_SUBSTRING_LENGTH = 10; // Length of seconds portion in microsecond timestamp string

type useSessionGameFilesProps = {
    sessionId?: string | undefined;
    live?: boolean;
    sessionStartTime?: string;
};

type File = {
    ID: string;
    filename: string;
    fileSizeBytes: number;
    uploadTimestamp: string;
    secondsFromSessionStart?: number;
};

const extractFilename = (path: string): string => {
    const parts = path.split('/');
    return parts[parts.length - 1] || path;
};

const fetchSessionGameFiles = async (sessionId: string): Promise<BagpiperRecord[]> => {
    try {
        const recordsResponse = await fetch(`/api/sessions/${sessionId}/gamefiles`);
        if (!recordsResponse.ok) {
            throw new Error('Failed to fetch game files');
        }

        const response: { data: BagpiperRecord[] } = await recordsResponse.json();
        return response.data;
    } catch (err) {
        throw err instanceof Error ? err : new Error('Failed to fetch game files');
    }
};

export const processRecords = (records: BagpiperRecord[], sessionStartTime?: string): File[] => {
    return records
        .map((record): File | null => {
            // Extract filename from path
            const filename = extractFilename(record.Path);

            // Parse file size from metadata
            const fileSizeBytes =
                record.Metadata.compressed === 'true'
                    ? Number(record.Metadata.compressed_size || 0)
                    : Number(record.Metadata.original_size || 0);

            // Calculate seconds from session start if we have both timestamps
            let secondsFromSessionStart: number | undefined;
            if (sessionStartTime && record.Metadata.upload_timestamp) {
                try {
                    // sessionStartTime is in microseconds (first 10 chars = seconds since epoch)
                    const sessionStartMs =
                        Number(sessionStartTime.slice(0, SECONDS_SUBSTRING_LENGTH)) * MILLISECONDS_PER_SECOND;
                    // upload_timestamp is in ISO format
                    const uploadTimeMs = new Date(record.Metadata.upload_timestamp).getTime();
                    secondsFromSessionStart = Math.round((uploadTimeMs - sessionStartMs) / MILLISECONDS_PER_SECOND);
                } catch (e) {
                    // Silently ignore timestamp calculation errors
                }
            }

            // Convert upload_timestamp to microseconds format for compatibility
            const uploadTimestamp = record.Metadata.upload_timestamp
                ? String(new Date(record.Metadata.upload_timestamp).getTime() * MICROSECONDS_PER_MILLISECOND)
                : record.CreatedAt
                  ? String(new Date(record.CreatedAt).getTime() * MICROSECONDS_PER_MILLISECOND)
                  : '0';

            return {
                ID: record.ID,
                filename,
                fileSizeBytes,
                uploadTimestamp,
                secondsFromSessionStart,
            };
        })
        .filter((file): file is File => file !== null);
};

export const useSessionGameFiles = ({ sessionId, sessionStartTime, live }: useSessionGameFilesProps = {}) => {
    const query = useQuery({
        queryKey: ['sessionGameFiles', sessionId],
        queryFn: () => fetchSessionGameFiles(sessionId!),
        enabled: !!sessionId,
        meta: {
            pollIntervalMs: live ? POLLING_INTERVAL_MS : undefined,
        },
    });

    // Process records with useMemo to separate fetching from processing
    const files = useMemo(() => {
        if (!query.data) {
            return [];
        }
        return processRecords(query.data, sessionStartTime);
    }, [query.data, sessionStartTime]);

    // Show error toast on failure (mimics original useEffect behavior)
    const { error, isError } = query;
    useEffect(() => {
        if (isError && sessionId) {
            const message = error instanceof Error ? error.message : 'Failed to fetch game files';
            createError({
                title: 'Error Loading Game Files',
                body: `Failed to load game files for session ${sessionId}: ${message}`,
                options: {
                    id: `game-files-fetch-error-${sessionId}`,
                    duration: ERROR_TOAST_DURATION_MS,
                },
            });
        }
    }, [isError, error, sessionId]);

    return {
        files,
        error: error
            ? {
                  type: 'Error' as const,
                  message: error instanceof Error ? error.message : 'Failed to fetch game files',
              }
            : undefined,
        isLoading: query.isLoading,
    };
};
