import { fetch } from '@gsm-app/utils/fetch';
import type { MessageType } from '@ocga/proto';
import { useEffect, useState } from 'react';

export type SessionEvent = {
    messageType: MessageType.MessageType;
    message: any;
    timestamp: string;
};

export interface Session {
    startTime: string;
    endTime: string;
    machineHostname: string;
    uuid: string;
    stackVersionBranch: string;
    stackVersionCommit: string;
    ocgaHardwareRevision?: string;
    events: SessionEvent[];
}

export interface GameSession {
    gameId: number;
    gameName: string;
    buildId: number;
    buildLabel: string;
    timestamp: string;
    live: boolean;
    id: string;
    esn: string;
    ocgaEnv: string;
    version: string;
    deviceName: string;
    videoHeight?: number;
    frameRate?: number;
    sessions: Session[];
    player?: string;
    playerUrl?: string;
    placeholder?: boolean;
    placeholderValue?: string;
}

export const useGameSession = (sessionId: string | undefined) => {
    const [state, setState] = useState<{ loading: boolean; error: undefined; data: GameSession | undefined }>({
        loading: true,
        error: undefined,
        data: undefined,
    });
    useEffect(() => {
        let ready = true;
        const controller = new AbortController();
        setState(() => ({
            loading: true,
            error: undefined,
            data: undefined,
        }));
        if (sessionId) {
            fetch(`/api/sessions/${sessionId}/info`, {
                signal: controller.signal,
            })
                .then(async (res) => {
                    const data = await res.json();
                    if (!res.ok) {
                        throw new Error(`${res.status} : ${data?.message ?? 'No Session'}`);
                    }
                    return data;
                })
                .then((data) => {
                    if (ready) {
                        setState(() => {
                            return {
                                loading: false,
                                error: undefined,
                                data: {
                                    ...data,
                                    id: sessionId,
                                },
                            };
                        });
                    }
                })
                .catch((error) => {
                    if (ready) {
                        setState(() => ({ loading: false, error, data: undefined }));
                    }
                });
        }

        return () => {
            ready = false;
            controller.abort();
        };
    }, [sessionId]);

    return state;
};
