import type { LogErrorWarningEvent } from '@gsm-app/hooks/useLogErrorWarningEvents';
import { isVirtualOcgaSession } from '@gsm-app/models/Channel';
import { StreamingMode } from '@gsm-app/models/StreamingMode';
import type { GameSession } from '@gsm-app/routes/Sessions/routes/SessionView/hooks/useGameSession';
import { ContextualBanner } from '@hawkins/components';
import type { ResourceEnvelope } from '@ncgt/resource-envelope';
import { SessionTimelineDataProvider } from '@ncgt/session-timeline';
import { ChartProvider } from '@ncgt/session-timeline/src/providers/ChartProvider';
import { SessionTimelineChart } from '../SessionTimelineChart';

export type SessionPerformanceChartProps = {
    session?: GameSession;
    datasets: { [key: string]: any };
    targetInstanceCount: number;
    error: string | null;
    exportOrder?: string[];
    loading: boolean;
    activeEnvelope: ResourceEnvelope | null;
    hidePerfGraphs: boolean;
    disablePerfGraphsNoEnvelope: boolean;
    /** Shared playhead position, in seconds from session start. Null when nothing is selected. */
    currentTime?: number | null;
    /** Epoch ms for t=0 (session start), shared with the logs list for consistent time matching. */
    sessionStartMs?: number;
    /** Which side last set currentTime — used to only auto pan the zoom window for log-originated jumps. */
    playheadSource?: 'graph' | 'log' | null;
    /** Called when the user clicks the graph's plot area, with the clicked time in seconds from session start. */
    onGraphPlayhead?: (seconds: number) => void;
    /** Error/warning markers derived from game + controller logs — always shown, below the screenshots row. */
    errorWarningEvents?: LogErrorWarningEvent[];
};

export const SessionPerformanceChart = ({
    session,
    datasets,
    targetInstanceCount,
    error,
    exportOrder,
    loading,
    activeEnvelope,
    hidePerfGraphs,
    disablePerfGraphsNoEnvelope,
    currentTime,
    sessionStartMs,
    playheadSource,
    onGraphPlayhead,
    errorWarningEvents,
}: SessionPerformanceChartProps) => {
    if (hidePerfGraphs) {
        return (
            <ContextualBanner
                text='Performance graphs are only available for sessions on OCGA 2026 hardware'
                variant='warning'
            />
        );
    }

    if (disablePerfGraphsNoEnvelope) {
        return (
            <ContextualBanner
                text='Performance graphs are not available for OCGA 2026 sessions without resource envelope data'
                variant='warning'
            />
        );
    }

    return (
        <SessionTimelineDataProvider
            data={datasets}
            isDisconnected={false}
            isLoading={loading}
            targetInstanceCount={targetInstanceCount}
            exportOrder={exportOrder}
            error={error}
        >
            <ChartProvider>
                <SessionTimelineChart
                    sessionId={session?.id}
                    mode={StreamingMode.OPEN}
                    hideInstanceCount={activeEnvelope != null}
                    isVirtualHardware={isVirtualOcgaSession(session?.sessions?.[0]?.machineHostname)}
                    currentTime={currentTime ?? null}
                    sessionStartMs={sessionStartMs ?? 0}
                    playheadSource={playheadSource}
                    onGraphPlayhead={onGraphPlayhead}
                    errorWarningEvents={errorWarningEvents}
                />
            </ChartProvider>
        </SessionTimelineDataProvider>
    );
};
