import {
    AllCommunityModule,
    type ColDef,
    type ColGroupDef,
    type ICellRendererParams,
} from 'ag-grid-community';
import {
    ColumnsToolPanelModule,
    FiltersToolPanelModule,
    MenuModule,
    SetFilterModule,
    SideBarModule,
} from 'ag-grid-enterprise';
import * as OcgaProto from '@ocga/proto';
import { ROUTE_SESSIONS } from '@gsm-app/constants';
import styles from './SessionHistoryTable.module.css'
import { createToast } from '@gsm-common/utils/toast/createToast';
import { createProgress } from '@gsm-common/utils/toast/createProgress';
import { download } from '@gsm-common/utils/file/download';
import { formatLog } from '@gsm-app/hooks/useSessionGameLogs';
import { toLog } from '@gsm-common/utils/file/toLog';
import { toCSV } from '@gsm-common/utils/file/toCSV';
import moment from 'moment';

import { useCallback, useEffect, useMemo, useState } from 'react';

import {
    Button,
    ContextualBanner,
    Menu,
    MenuGroup,
    MenuItem,
    SkeletonLoader,
    Stack,
    Text,
    Tooltip
} from '@hawkins/components';
import { TableNext } from '@hawkins/table-next';
import { Dimensions } from '@hawkins/variables';
import { type SessionHistoryEntry, useSessionHistory } from '../../hooks/useSessionHistory';
import { useFullStory } from '@gsm-app/hooks/useFullStory';
import { type SopAccountType, useSopAccounts } from '@gsm-app/providers/SopAccountProvider';
import { IconCheckmark, IconCircleX, IconClipboard, IconDownload, IconLinkOut } from '@hawkins/assets';
import { PAGINATION_OPTIONS, PAGINATION_PAGE_SIZE } from '@gsm-app/constants';
import { useGames } from '@gsm-app/hooks/useGames';
import { useSuccessfulSessionsByIds } from '../../hooks/useSuccessfulSessionsByIds';

function humanizeDuration(rawMs: number): string {
    const duration = moment.duration(rawMs);
    const minutes = Math.floor(duration.asMinutes());
    const seconds = duration.seconds();

    if (minutes === 0 && seconds === 0) {
        return `${Math.round(rawMs)}ms`;
    }

    let result = '';
    if (minutes > 0) result += `${minutes}m `;
    if (seconds > 0 || minutes > 0) result += `${seconds}s`;

    return result.trim();
}

export const SessionHistoryTable = () => {
    const { data: games } = useGames();
    const { selectedAccount: sopAccount, isLoading: sopAccountsLoading, savedAccounts } = useSopAccounts();
    const [selectedAccount, setSelectedAccount] = useState<SopAccountType | undefined>();

    const {
        error,
        isLoading,
        sessions,
        buildDisplayNames,
        esnFriendlyNames
    } = useSessionHistory(selectedAccount?.value);
    const { successfulSessionsById, isLoading: successfulSessionsByIdLoading, error: successfulSessionsByIdError } = useSuccessfulSessionsByIds(sessions.map((s) => s.gameplaySessionId));

    const [downloadingSessionId, setDownloadingSessionId] = useState<string | undefined>();
    const { trackEvent } = useFullStory();

    useEffect(() => {
        if (sopAccount) {
            setSelectedAccount(sopAccount);
        }
    }, [sopAccount?.value]);

    const modules = useMemo(
        () => [
            AllCommunityModule,
            SetFilterModule,
            MenuModule,
            SideBarModule,
            ColumnsToolPanelModule,
            FiltersToolPanelModule,
        ],
        [],
    );

    const downloadSession = useCallback((gameplaySessionId: string, formatter: any, format: any) => {
        setDownloadingSessionId(gameplaySessionId);
        const downloadPromise = fetch(
            `/api/t2/${gameplaySessionId}?${new URLSearchParams({
                messageTypes: [OcgaProto.MessageType.MessageType.LogEvent].join(','),
                method: 'rest',
                download: 'true',
            })}`).then(async (result) => {
                const jsonResult = await result.json();
                const rawLogs = jsonResult.data;
                const logs = rawLogs.map((event: any) => {
                    const formattedLog = formatLog(event);
                    return formattedLog;
                }).filter(Boolean);
                const name = `browser_game_logs_${gameplaySessionId}_${Date.now()}`
                download(name, formatter(logs), format);
            })
            .finally(() => {
                setDownloadingSessionId(undefined);
            });

        createProgress(downloadPromise, {
            title: {
                loading: 'Downloading...',
                success: 'Session downloaded',
                error: 'Error downloading session',
            },
            options: {
                id: `history_${gameplaySessionId}`
            }
        });
        setDownloadingSessionId(gameplaySessionId);
    }, []);

    const copyEsnToClipboard = useCallback((esn: string) => {
        navigator.clipboard.writeText(esn);
        createToast({
            title: 'Copied URL to clipboard',
            options: {
                id: esn,
                duration: 1000,
            },
        })
    }, []);

    const columnDefs = useMemo<(ColDef<SessionHistoryEntry> | ColGroupDef<SessionHistoryEntry>)[]>(() => {
        const twoWeeksInMs = 14 * 24 * 60 * 60 * 1000;
        const now = new Date().getTime();
        return [
            {
                field: 'gameplaySessionId',
                headerName: 'Id',
                filter: 'agTextColumnFilter',
                cellStyle: {
                    overflow: 'hidden',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                },
                width: 284,
                cellRenderer: (params: ICellRendererParams<SessionHistoryEntry, string>) => {
                    return (
                        <Button
                            icon={IconLinkOut}
                            compact
                            variant='tertiary'
                            onClick={() => {
                                trackEvent('Session History Launch', {
                                    email: selectedAccount?.value,
                                    gameplaySessionId: params.value,
                                });
                            }}
                            to={`${ROUTE_SESSIONS}/${params.value}`}
                            target='_blank'
                            className={styles.fullWidthSessionButton}
                        >
                            {params.value}
                        </Button>
                    );
                }
            },
            {
                field: 'gameId',
                headerName: 'Game',
                filter: 'agTextColumnFilter',
                cellStyle: {
                    overflow: 'hidden',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'start',
                },
                cellRenderer: (params: ICellRendererParams<SessionHistoryEntry, string>) => {
                    const game = games.find((game) => game.id === `${params.value}`);
                    if (game) {
                        return <Text>{game.title} <Text component='span' variant='label' level={2} colorVariant='faded'>({params.value})</Text></Text>;
                    }

                    return params.value;
                }
            },
            {
                field: 'buildId',
                filter: 'agTextColumnFilter',
                headerName: 'Build',
                minWidth: 336,
                cellStyle: {
                    overflow: 'hidden',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'start',
                },
                cellRenderer: (params: ICellRendererParams<SessionHistoryEntry, string>) => {
                    if (params.value && buildDisplayNames[params.value]) {
                        const displayName = buildDisplayNames[params.value];
                        // Parse format: "<label string> (<number>)"
                        const match = displayName.match(/^(.+?)\s+\(([^)]+)\)$/);
                        if (match) {
                            const [, label, buildNumber] = match;
                            return <Text>{label} <Text component='span' variant='label' level={2} colorVariant='faded'>({buildNumber})</Text></Text>;
                        }
                        return displayName;
                    }
                    return params.value;
                }
            },
            {
                field: 'startTime',
                headerName: 'Started',
                filter: 'agDateColumnFilter',
                maxWidth: 156,
                cellRenderer: (params: ICellRendererParams<SessionHistoryEntry>) => {
                    const date = new Date(params.value);
                    return date.toLocaleDateString(undefined, {
                        year: '2-digit', // Short year format, like '24'
                        month: '2-digit', // Numeric month format, like '11'
                        day: '2-digit', // Numeric day format, like '08'
                        hour: '2-digit', // 2-digit hour
                        minute: '2-digit', // 2-digit minute
                    });
                },
            },
            {
                field: 'duration',
                headerName: 'Duration',
                editable: false,
                floatingFilter: false,
                resizable: false,
                sortable: false,
                filter: false,
                suppressHeaderMenuButton: true,
                suppressHeaderContextMenu: true,
                maxWidth: 86,
                cellRenderer: (params: ICellRendererParams<SessionHistoryEntry, number>) => {
                    return params.value ? humanizeDuration(params.value) : null;
                },
            },
            {
                field: 'version',
                filter: 'agTextColumnFilter',
                headerName: 'OCGA Version',
            },
            {
                field: 'ocgaEnv',
                filter: 'agSetColumnFilter',
                headerName: 'OCGA Env',
            },
            {
                field: 'hardwareRevision',
                headerName: 'Hardware',
                filter: 'agSetColumnFilter',
            },
            {
                field: 'esn',
                headerName: 'Device Name',
                cellRenderer: (params: ICellRendererParams<SessionHistoryEntry, string>) => {
                    return (
                        params.value && esnFriendlyNames[params.value] ? (
                            esnFriendlyNames[params.value]
                        ) : null
                    )
                },
            },
            {
                field: 'esn',
                headerName: 'Client ESN',
                flex: 1,
                cellRenderer: (params: ICellRendererParams<SessionHistoryEntry, string>) => {
                    return (
                        <Stack orientation='horizontal'
                            gap={Dimensions.Space4}
                            className={styles.esnWrapper}
                        >
                            <Text component='div' className={styles.esnLabel}>
                                {params.value}
                            </Text>
                            <Button
                                className={styles.esnCopy}
                                variant='icon'
                                aria-label='Copy ESN to clipboard'
                                icon={IconClipboard}
                                compact
                                onClick={() => {
                                    if (params.value) {
                                        copyEsnToClipboard(params.value);
                                    }
                                }}
                            />
                        </Stack>
                    )
                },
            },
            {
                headerName: '',
                sortable: false,
                filter: false,
                maxWidth: Dimensions.RawSize56,
                suppressHeaderMenuButton: true,
                suppressHeaderContextMenu: true,
                cellStyle: {
                    overflow: 'hidden',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                },
                cellRenderer: (params: ICellRendererParams<SessionHistoryEntry>) => {
                    if (!params.data?.startTime || !params.data?.gameplaySessionId) {
                        return null;
                    }
                    const startTime: number = params.data.startTime;
                    const gameplaySessionId: string = params.data.gameplaySessionId;
                    const sessionDate = new Date(startTime).getTime();
                    const telemetryExpired = now - sessionDate >= twoWeeksInMs;
                    return (
                        <Menu classes={{
                            triggerContainer: styles.actionMenuContainer
                        }} trigger={
                            <Button
                                variant='icon'
                                compact
                                tooltipLabel={telemetryExpired ? 'Older sessions are not available' : null}
                                disabled={telemetryExpired}
                                executing={downloadingSessionId === gameplaySessionId}
                                icon={IconDownload}
                                aria-label='download'
                            />
                        }>
                            <MenuGroup label='FORMATS'>
                                <MenuItem key='log' label='Log' onClick={() => downloadSession(gameplaySessionId, toLog, 'log')} />
                                <MenuItem key='csv' label='CSV' onClick={() => downloadSession(gameplaySessionId, toCSV, 'csv')} />
                            </MenuGroup>
                        </Menu>
                    )
                },
            },
            {
                field: 'gameplaySessionId',
                headerName: 'Successful',
                filter: false,
                sortable: false,
                floatingFilter: false,
                suppressHeaderMenuButton: true,
                suppressHeaderContextMenu: true,
                maxWidth: 100,
                cellStyle: {
                    overflow: 'hidden',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                },
                cellRenderer: (params: ICellRendererParams<SessionHistoryEntry, string>) => {
                    const isSuccessful = params.value && successfulSessionsById[params.value];
                    if (successfulSessionsByIdLoading) {
                        return <SkeletonLoader height={Dimensions.Size16} width={Dimensions.Size16} />;
                    } else if (successfulSessionsByIdError) {
                        return (
                            <Tooltip label='Unable to get successful session data'>
                                <IconCircleX size='small' />
                            </Tooltip>
                        );
                    }
                    return isSuccessful ? <IconCheckmark size='small' /> : null;
                },
            },
        ];
    }, [
        esnFriendlyNames,
        buildDisplayNames,
        downloadingSessionId,
        games,
        selectedAccount?.value,
        copyEsnToClipboard,
        downloadSession,
        trackEvent,
        successfulSessionsById,
        successfulSessionsByIdError,
        successfulSessionsByIdLoading
    ]);

    const defaultColDef = useMemo<ColDef>(() => {
        return {
            editable: false,
            filter: true,
            floatingFilter: true,
            minWidth: 100,
            resizable: true,
            sortable: true,
        };
    }, []);

    const autoGroupColumnDef = useMemo<ColDef>(() => {
        return {
            cellRendererParams: {
                checkbox: false,
                suppressCount: false,
            },
            headerName: 'Group',
            menuTabs: [],
            minWidth: 250,
        };
    }, []);

    return error ? (
        <ContextualBanner variant='error' text='Error loading Session History' />
    ) : (
        <div style={{
            background: 'red',
            display: 'flex',
            flexDirection: 'column',
            height: 'auto',
            flex: 1,
            width: '100%'
        }}>
            <TableNext<SessionHistoryEntry>
                animateRows={true}
                loading={isLoading}
                autoGroupColumnDef={autoGroupColumnDef}
                columnDefs={columnDefs}
                enableCellTextSelection={true}
                ensureDomOrder={true}
                defaultColDef={defaultColDef}
                groupDefaultExpanded={1}
                modules={modules}
                pagination={true}
                paginationPageSize={PAGINATION_PAGE_SIZE}
                paginationPageSizeSelector={PAGINATION_OPTIONS}
                rowData={sessions}
                style={{ height: '100%', width: '100%' }}
            />
        </div>
    );
};
