import { fetch } from '@gsm-app/utils/fetch';
import { useQuery } from '@tanstack/react-query';
import { useMemo } from 'react';

export interface SessionHistoryEntry {
    gameplaySessionId: string;
    gameId: string;
    esn: string;
    buildId?: string;
    startTime: number;
    endTime: number;
    ocgaEnv?: string;
    version?: string;
    duration?: number;
    hardwareRevision?: string;
}

export interface SessionHistoryResponse {
    data?: {
        sessions: SessionHistoryEntry[];
        esnFriendlyNames: any;
        buildDisplayNames: any;
    };
    errors?: {
        title: string;
        detail: string;
    }[];
}

const fetchSessionHistory = async (email: string | undefined): Promise<SessionHistoryResponse | undefined> => {
    if (!email) {
        return Promise.resolve(undefined);
    }
    const response = await fetch('/api/sessions/history', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            email,
        }),
    });

    if (!response.ok) {
        const errorData = await response.text();
        throw new Error(`Fetch failed with status ${response.status}: ${errorData}`);
    }
    return await response.json();
};

export function useSessionHistory(email: string | undefined) {
    const query = useQuery({
        queryKey: ['session-history', email],
        queryFn: () => fetchSessionHistory(email),
        enabled: Boolean(email),
    });

    const sessions = useMemo(() => {
        return query.data?.data?.sessions || [];
    }, [email, query.data]);

    const esnFriendlyNames = useMemo(() => {
        return query.data?.data?.esnFriendlyNames || {};
    }, [email, query.data]);

    const buildDisplayNames = useMemo(() => {
        return query.data?.data?.buildDisplayNames || {};
    }, [email, query.data]);

    return {
        sessions,
        esnFriendlyNames,
        buildDisplayNames,
        ...query,
    };
}
