import { LOG_TYPE_ICON_COLOR } from '@gsm-app/components/LogViewer/logTypeUtils';
import type { LogErrorWarningEvent } from '@gsm-app/hooks/useLogErrorWarningEvents';
import { IconJumpTo } from '@hawkins/assets';
import { Button, Tag, Text, Tooltip } from '@hawkins/components';
import { AllCommunityModule, type ColDef, type ICellRendererParams, TableNext } from '@hawkins/table-next';
import { RowGroupingModule } from 'ag-grid-enterprise';
import { useMemo } from 'react';
import { templatizeMessage } from './messageTemplate';

type ErrorRow = {
    groupKey: string;
    severity: 'Error' | 'Warning';
    source: 'Game' | 'Controller';
    timestampMs: number;
    message: string;
};

export interface SessionErrorsTableProps {
    events: LogErrorWarningEvent[];
    /** Jumps the Performance tab's shared playhead to this occurrence's exact time. */
    onJumpToTime: (date: Date) => void;
}

const SEVERITY_COLOR: Record<ErrorRow['severity'], string | undefined> = {
    Error: LOG_TYPE_ICON_COLOR.error,
    Warning: LOG_TYPE_ICON_COLOR.warn,
};

const modules = [AllCommunityModule, RowGroupingModule];

export const SessionErrorsTable = ({ events, onJumpToTime }: SessionErrorsTableProps) => {
    // Group by (severity + normalized message template) so hundreds of near-duplicate log lines
    // — which usually only differ by an embedded frame number / address / id — collapse into a
    // single, collapsible group instead of flooding the table with one row per raw occurrence.
    const rowData = useMemo<ErrorRow[]>(() => {
        const counts = new Map<string, number>();
        const keyFor = (e: LogErrorWarningEvent) =>
            `${e.severity === 'error' ? 'Error' : 'Warning'} — ${templatizeMessage(e.message)}`;
        for (const e of events) {
            const key = keyFor(e);
            counts.set(key, (counts.get(key) ?? 0) + 1);
        }

        // Order by group frequency (most repeated issue first), then chronologically within a
        // group — AG Grid's row grouping preserves first-seen order for the groups themselves.
        const sorted = [...events].sort((a, b) => {
            const keyA = keyFor(a);
            const keyB = keyFor(b);
            const countDiff = (counts.get(keyB) ?? 0) - (counts.get(keyA) ?? 0);
            if (countDiff !== 0) return countDiff;
            if (keyA !== keyB) return keyA.localeCompare(keyB);
            return a.date.getTime() - b.date.getTime();
        });

        return sorted.map((e) => ({
            groupKey: keyFor(e),
            severity: e.severity === 'error' ? ('Error' as const) : ('Warning' as const),
            source: e.source === 'game' ? ('Game' as const) : ('Controller' as const),
            timestampMs: e.date.getTime(),
            message: e.message,
        }));
    }, [events]);

    const columnDefs = useMemo<ColDef<ErrorRow>[]>(
        () => [
            { field: 'groupKey', rowGroup: true, hide: true },
            {
                headerName: 'Severity',
                field: 'severity',
                flex: 0.7,
                minWidth: 100,
                cellRenderer: (params: ICellRendererParams<ErrorRow, ErrorRow['severity']>) => {
                    if (!params.value) return null;
                    return <Tag style={{ color: SEVERITY_COLOR[params.value] }}>{params.value}</Tag>;
                },
            },
            {
                headerName: 'Source',
                field: 'source',
                flex: 0.6,
                minWidth: 90,
            },
            {
                headerName: 'Time',
                field: 'timestampMs',
                flex: 0.9,
                minWidth: 140,
                // Shows the most recent occurrence on the collapsed group row ("Last seen").
                aggFunc: 'max',
                valueFormatter: (params) => (params.value != null ? new Date(params.value).toLocaleString() : ''),
            },
            {
                headerName: 'Message',
                field: 'message',
                flex: 3,
                minWidth: 240,
                tooltipField: 'message',
            },
            {
                headerName: '',
                flex: 0.4,
                minWidth: 44,
                sortable: false,
                filter: false,
                cellRenderer: (params: ICellRendererParams<ErrorRow>) => {
                    if (params.node.group || !params.data) return null;
                    const { timestampMs, message } = params.data;
                    return (
                        <Tooltip label='Jump to this moment in the performance graph'>
                            <Button
                                variant='icon'
                                compact
                                icon={IconJumpTo}
                                aria-label={`Jump to ${message} in the performance graph`}
                                onClick={() => onJumpToTime(new Date(timestampMs))}
                            />
                        </Tooltip>
                    );
                },
            },
        ],
        [onJumpToTime],
    );

    const autoGroupColumnDef = useMemo<ColDef<ErrorRow>>(
        () => ({
            headerName: 'Error / Warning',
            flex: 2,
            minWidth: 280,
            cellRendererParams: { suppressCount: false },
        }),
        [],
    );

    const defaultColDef = useMemo<ColDef<ErrorRow>>(
        () => ({
            sortable: true,
            resizable: true,
        }),
        [],
    );

    return (
        <div style={{ height: 420, width: '100%' }}>
            <TableNext<ErrorRow>
                rowData={rowData}
                columnDefs={columnDefs}
                autoGroupColumnDef={autoGroupColumnDef}
                defaultColDef={defaultColDef}
                groupDefaultExpanded={0}
                modules={modules}
                pagination
                paginationPageSize={20}
                paginationPageSizeSelector={[20, 50, 100]}
                domLayout='normal'
                style={{ height: '100%', width: '100%' }}
                noRowsOverlayComponent={() => (
                    <Text colorVariant='faded'>No errors or warnings recorded for this session</Text>
                )}
            />
        </div>
    );
};
